#include <iostream>
#include <nlohmann/json.hpp>
#include <nlohmann/json_view.hpp>

int main() {
    try {
        const std::string text = R"({"abcdefgh": 1, "abcd": 2, "xyz": 3})";
        auto doc = nlohmann::json_document::parse(text);
        auto view = doc.root();
        for (auto it = view.begin(); it != view.end(); ++it) {
            std::cout << "Key size: " << it.key().size() << " value: " << it->materialize() << std::endl;
        }
    } catch (const std::exception& e) {
        std::cout << "Exception: " << e.what() << std::endl;
    }
    return 0;
}
